function validateOrder(unvalidatedOrder) {
  if (!unvalidatedOrder.customerId) {
    return { tag: 'Error', message: '缺少 customerId' };
  }
  return { tag: 'Ok', order: { ...unvalidatedOrder, validated: true } };
}

console.log(validateOrder({ customerId: 'C1' }));
console.log(validateOrder({}));

