function validateOrder(checkProductExists, unvalidatedOrder) {
  if (!checkProductExists(unvalidatedOrder.productId)) {
    return { tag: 'Error', message: `商品 ${unvalidatedOrder.productId} 不存在` };
  }
  return { tag: 'Ok', order: unvalidatedOrder };
}

const fakeCheckProductExists = () => false;

console.log(validateOrder(fakeCheckProductExists, { productId: 'P999' }));

